{"task": "customer-fk", "steps": [
  {"note": "Add the foreign key as NOT VALID: from now on every new or updated order must reference an existing customer, but the 10M existing rows are not scanned, so the SHARE ROW EXCLUSIVE lock on orders/customers is held only for a moment. lock_timeout 500ms keeps app inserts (2 s statement timeout) from queueing behind us if we can't get the lock right away; on timeout it retries, up to 60 times. Skips if the constraint already exists.",
   "sql": "DO $$ BEGIN IF EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'orders'::regclass AND conname = 'orders_customer_id_fkey') THEN RETURN; END IF; FOR i IN 1..60 LOOP BEGIN PERFORM set_config('lock_timeout', '500ms', true); ALTER TABLE orders ADD CONSTRAINT orders_customer_id_fkey FOREIGN KEY (customer_id) REFERENCES customers (id) NOT VALID; RETURN; EXCEPTION WHEN lock_not_available THEN PERFORM pg_sleep(1); END; END LOOP; RAISE EXCEPTION 'could not lock orders/customers to add orders_customer_id_fkey after 60 tries'; END $$;"},
  {"note": "Validate the existing rows. VALIDATE CONSTRAINT takes only SHARE UPDATE EXCLUSIVE on orders (and ROW SHARE on customers), so app reads and inserts keep running while it scans the 10M rows. No statement timeout, since the scan can take a while. If any order points at a missing customer this fails and the plan stops, leaving the constraint in place (enforced for new rows) and the bad rows untouched for a person to decide on.",
   "sql": "SET statement_timeout = 0; SET lock_timeout = 0; ALTER TABLE orders VALIDATE CONSTRAINT orders_customer_id_fkey;"},
  {"note": "Check: the foreign key exists and is validated.",
   "sql": "DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'orders'::regclass AND conname = 'orders_customer_id_fkey' AND contype = 'f' AND convalidated) THEN RAISE EXCEPTION 'orders_customer_id_fkey is missing or not validated'; END IF; END $$;"}
]}
